'use client';

import { useId, useState } from 'react';
import { useTranslations } from 'next-intl';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';
import { FieldError, PasswordVisibilityToggle, SubmitButton } from '@/components/forms';
import { useCreateUserMutation } from '@/store/api/userApi';
import { useListRolesQuery } from '../api/rolesApi';
import { toast } from '@/lib/toast';
import { parseApiError } from '@/lib/apiError';
import { validateCreateUserForm } from '../utils/createUserValidation';

export interface CreateUserDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Optional callback when user is created successfully */
  onSuccess?: () => void;
}

/**
 * CreateUserDialog - Modal for creating new users
 *
 * Features:
 * - Email, name, password input fields
 * - Role selector (non-protected roles only)
 * - Form validation
 * - Error handling
 * - Loading states
 *
 * @example
 * ```tsx
 * const [open, setOpen] = useState(false);
 * <CreateUserDialog open={open} onOpenChange={setOpen} />
 * ```
 */
export function CreateUserDialog({ open, onOpenChange, onSuccess }: CreateUserDialogProps) {
  const t = useTranslations('users.createUser');
  const tValidation = useTranslations('validation');
  const tCommon = useTranslations('common');
  const uid = useId();
  const fieldId = (name: string) => `${uid}-${name}`;
  const errorId = (name: string) => `${uid}-${name}-error`;
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [createUser, { isLoading }] = useCreateUserMutation();
  const { data: rolesData, isLoading: isLoadingRoles } = useListRolesQuery(undefined);

  const roles = rolesData?.roles || [];
  const availableRoles = roles.filter((r) => !r.isProtected);

  const validateForm = (): boolean => {
    const newErrors = validateCreateUserForm({ email, name, password, role }, tValidation);
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      await createUser({
        email: email.trim(),
        name: name.trim(),
        password,
        role,
      }).unwrap();

      toast.success(t('success'));
      handleClose();
      onSuccess?.();
    } catch (error) {
      const parsed = parseApiError(error);
      toast.error(parsed.message || t('error'));
    }
  };

  const handleClose = () => {
    setEmail('');
    setName('');
    setPassword('');
    setRole('user');
    setShowPassword(false);
    setErrors({});
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]" data-testid="create-user-dialog">
        <DialogHeader>
          <DialogTitle className="text-xl font-semibold tracking-tight">{t('title')}</DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {t('description')}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} noValidate className="space-y-5">
          {/* Email Field */}
          <div className="space-y-2">
            <Label
              htmlFor={fieldId('email')}
              className="text-xs uppercase tracking-widest text-muted-foreground"
            >
              {t('email')}
            </Label>
            <Input
              id={fieldId('email')}
              type="email"
              placeholder={t('emailPlaceholder')}
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                if (errors.email) setErrors((prev) => ({ ...prev, email: '' }));
              }}
              disabled={isLoading}
              aria-invalid={Boolean(errors.email)}
              aria-describedby={errors.email ? errorId('email') : undefined}
              className={errors.email ? 'border-destructive' : ''}
              data-testid="create-user-email-input"
            />
            <FieldError id={errorId('email')} message={errors.email} testId="email-error" />
          </div>

          {/* Name Field */}
          <div className="space-y-2">
            <Label
              htmlFor={fieldId('name')}
              className="text-xs uppercase tracking-widest text-muted-foreground"
            >
              {t('name')}
            </Label>
            <Input
              id={fieldId('name')}
              type="text"
              placeholder={t('namePlaceholder')}
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                if (errors.name) setErrors((prev) => ({ ...prev, name: '' }));
              }}
              disabled={isLoading}
              aria-invalid={Boolean(errors.name)}
              aria-describedby={errors.name ? errorId('name') : undefined}
              className={errors.name ? 'border-destructive' : ''}
              data-testid="create-user-name-input"
            />
            <FieldError id={errorId('name')} message={errors.name} testId="name-error" />
          </div>

          {/* Password Field */}
          <div className="space-y-2">
            <Label
              htmlFor={fieldId('password')}
              className="text-xs uppercase tracking-widest text-muted-foreground"
            >
              {t('password')}
            </Label>
            <div className="relative">
              <Input
                id={fieldId('password')}
                type={showPassword ? 'text' : 'password'}
                placeholder="••••••••"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  if (errors.password) setErrors((prev) => ({ ...prev, password: '' }));
                }}
                disabled={isLoading}
                aria-invalid={Boolean(errors.password)}
                aria-describedby={errors.password ? errorId('password') : undefined}
                className={errors.password ? 'border-destructive pe-10' : 'pe-10'}
                data-testid="create-user-password-input"
              />
              <PasswordVisibilityToggle
                showPassword={showPassword}
                onToggle={() => setShowPassword(!showPassword)}
                testId="create-user-password-toggle"
              />
            </div>
            <FieldError
              id={errorId('password')}
              message={errors.password}
              testId="password-error"
            />
          </div>

          {/* Role Field */}
          <div className="space-y-2">
            <Label
              htmlFor={fieldId('role')}
              className="text-xs uppercase tracking-widest text-muted-foreground"
            >
              {t('role')}
            </Label>
            <Select
              value={role}
              onValueChange={(value) => {
                setRole(value);
                if (errors.role) setErrors((prev) => ({ ...prev, role: '' }));
              }}
              disabled={isLoading || isLoadingRoles}
            >
              <SelectTrigger
                id={fieldId('role')}
                aria-invalid={Boolean(errors.role)}
                aria-describedby={errors.role ? errorId('role') : undefined}
                className={errors.role ? 'border-destructive' : ''}
                data-testid="create-user-role-select"
              >
                {isLoadingRoles ? (
                  <Loader2 className="h-4 w-4 motion-safe:animate-spin" aria-hidden="true" />
                ) : (
                  <SelectValue placeholder={t('selectRole')} />
                )}
              </SelectTrigger>
              <SelectContent>
                {availableRoles.map((r) => (
                  <SelectItem key={r.id} value={r.slug} data-testid={`role-option-${r.slug}`}>
                    <div className="flex items-center gap-2">
                      <span>{r.name}</span>
                      {r.isSystemRole && (
                        <span className="text-xs text-tertiary">{t('systemRole')}</span>
                      )}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <FieldError id={errorId('role')} message={errors.role} testId="role-error" />
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              type="button"
              variant="ghost"
              onClick={handleClose}
              disabled={isLoading}
              data-testid="cancel-create-user-button"
            >
              {tCommon('cancel')}
            </Button>
            <SubmitButton
              isLoading={isLoading}
              loadingText={t('creating')}
              className="h-10 mt-0 w-auto py-2"
              testId="submit-create-user-button"
            >
              {t('submit')}
            </SubmitButton>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}
'use client';

import { useId, useState } from 'react';
import { useTranslations } from 'next-intl';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { FieldError, SubmitButton } from '@/components/forms';
import { useCreateRoleMutation } from '../api/rolesApi';
import { PermissionSelector } from './PermissionSelector';
import { toast } from '@/lib/toast';
import { parseApiError } from '@/lib/apiError';

export interface CreateRoleDialogProps {
  /**
   * Whether the dialog is open
   */
  open: boolean;

  /**
   * Callback when dialog should close
   */
  onOpenChange: (open: boolean) => void;

  /**
   * Callback when role is successfully created
   */
  onSuccess?: () => void;
}

interface RoleFormErrors {
  name?: string;
  permissions?: string;
}

/**
 * Dialog for creating a new role. Validation problems are shown under the field
 * they belong to and linked with `aria-describedby`, not only as a toast.
 *
 * @example
 * ```tsx
 * const [open, setOpen] = useState(false);
 *
 * <CreateRoleDialog open={open} onOpenChange={setOpen} onSuccess={refetch} />
 * ```
 */
export function CreateRoleDialog({ open, onOpenChange, onSuccess }: CreateRoleDialogProps) {
  const t = useTranslations('roles.form');
  const uid = useId();
  const nameId = `${uid}-name`;
  const nameErrorId = `${uid}-name-error`;
  const descriptionId = `${uid}-description`;
  const permissionsLabelId = `${uid}-permissions-label`;
  const permissionsErrorId = `${uid}-permissions-error`;

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [permissions, setPermissions] = useState<string[]>([]);
  const [errors, setErrors] = useState<RoleFormErrors>({});

  const [createRole, { isLoading }] = useCreateRoleMutation();

  const resetForm = () => {
    setName('');
    setDescription('');
    setPermissions([]);
    setErrors({});
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const nextErrors: RoleFormErrors = {};
    if (!name.trim()) nextErrors.name = t('nameError');
    if (permissions.length === 0) nextErrors.permissions = t('permissionsError');

    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    try {
      await createRole({
        name: name.trim(),
        description: description.trim() || undefined,
        permissions,
      }).unwrap();

      toast.success(t('createSuccess', { name: name.trim() }));
      resetForm();
      onOpenChange(false);
      onSuccess?.();
    } catch (error: unknown) {
      const parsed = parseApiError(error);
      toast.error(parsed.message || t('error'));
    }
  };

  const handleCancel = () => {
    resetForm();
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-h-[90vh] max-w-3xl overflow-y-auto"
        data-testid="create-role-dialog"
      >
        <form onSubmit={handleSubmit} noValidate>
          <DialogHeader>
            <DialogTitle>{t('createTitle')}</DialogTitle>
            <DialogDescription>{t('createDescription')}</DialogDescription>
          </DialogHeader>

          <div className="space-y-6 py-6">
            {/* Role Name */}
            <div className="space-y-2">
              <Label htmlFor={nameId}>
                {t('nameLabel')} <span className="text-destructive">{t('nameRequired')}</span>
              </Label>
              <Input
                id={nameId}
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  if (errors.name) setErrors((prev) => ({ ...prev, name: undefined }));
                }}
                placeholder={t('namePlaceholder')}
                disabled={isLoading}
                required
                aria-invalid={Boolean(errors.name)}
                aria-describedby={errors.name ? nameErrorId : undefined}
                data-testid="role-name-input"
              />
              <FieldError id={nameErrorId} message={errors.name} testId="role-name-error" />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor={descriptionId}>{t('descriptionLabel')}</Label>
              <Textarea
                id={descriptionId}
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder={t('descriptionPlaceholder')}
                rows={3}
                disabled={isLoading}
                data-testid="role-description-input"
              />
            </div>

            {/* Permissions */}
            <div className="space-y-2">
              <Label id={permissionsLabelId}>
                {t('permissionsLabel')}{' '}
                <span className="text-destructive">{t('permissionsRequired')}</span>
              </Label>
              <div
                role="group"
                aria-labelledby={permissionsLabelId}
                aria-describedby={errors.permissions ? permissionsErrorId : undefined}
              >
                <PermissionSelector
                  selectedPermissions={permissions}
                  onChange={(next) => {
                    setPermissions(next);
                    if (errors.permissions) {
                      setErrors((prev) => ({ ...prev, permissions: undefined }));
                    }
                  }}
                  disabled={isLoading}
                />
              </div>
              <FieldError
                id={permissionsErrorId}
                message={errors.permissions}
                testId="role-permissions-error"
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={handleCancel}
              disabled={isLoading}
              data-testid="cancel-button"
            >
              {t('cancel')}
            </Button>
            <SubmitButton
              isLoading={isLoading}
              loadingText={t('creating')}
              className="h-10 mt-0 w-auto py-2"
              testId="create-role-button"
            >
              {t('create')}
            </SubmitButton>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}
'use client';

import { useId, useState } from 'react';
import { useTranslations } from 'next-intl';
import { DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { FieldError, SubmitButton } from '@/components/forms';
import { PermissionSelector } from './PermissionSelector';
import type { Role } from '../api/rolesApi';

export interface EditRoleFormValues {
  name: string;
  description: string;
  permissions: string[];
}

export interface EditRoleFormProps {
  role: Role;
  isLoading: boolean;
  onSubmit: (data: EditRoleFormValues) => void;
  onCancel: () => void;
}

interface EditRoleFormErrors {
  name?: string;
  permissions?: string;
}

/**
 * Body of the edit dialog. It remounts when the role changes through a key prop,
 * so the fields start from the role that is being edited.
 */
export function EditRoleForm({ role, isLoading, onSubmit, onCancel }: EditRoleFormProps) {
  const t = useTranslations('roles.form');
  const uid = useId();
  const nameId = `${uid}-name`;
  const nameErrorId = `${uid}-name-error`;
  const descriptionId = `${uid}-description`;
  const permissionsLabelId = `${uid}-permissions-label`;
  const permissionsErrorId = `${uid}-permissions-error`;

  const [name, setName] = useState(role.name || '');
  const [description, setDescription] = useState(role.description || '');
  const [permissions, setPermissions] = useState<string[]>(role.permissions || []);
  const [errors, setErrors] = useState<EditRoleFormErrors>({});

  const isProtected = role.isProtected;
  const isBaseRole = role.slug === 'user' || role.slug === 'admin';

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const nextErrors: EditRoleFormErrors = {};
    if (!name.trim()) nextErrors.name = t('nameError');
    if (permissions.length === 0) nextErrors.permissions = t('permissionsError');

    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    onSubmit({ name, description, permissions });
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      <DialogHeader>
        <DialogTitle>{t('editTitle', { name: role.name })}</DialogTitle>
        <DialogDescription>{t('editDescription')}</DialogDescription>
      </DialogHeader>

      <div className="space-y-6 py-6">
        {isBaseRole && (
          <Alert variant="info" role="note" data-testid="base-role-note">
            <AlertDescription>
              <strong>Base Role:</strong> User and Admin roles are fundamental to the system. Name
              and description cannot be modified, but you can update permissions.
            </AlertDescription>
          </Alert>
        )}

        {isProtected && !isBaseRole && (
          <Alert variant="warning" role="note" data-testid="protected-role-note">
            <AlertDescription>
              <strong>Protected Role:</strong> This role cannot be deleted and its core permissions
              are managed by the system.
            </AlertDescription>
          </Alert>
        )}

        {/* Role Name */}
        <div className="space-y-2">
          <Label htmlFor={nameId}>
            {t('nameLabel')} <span className="text-destructive">{t('nameRequired')}</span>
          </Label>
          <Input
            id={nameId}
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              if (errors.name) setErrors((prev) => ({ ...prev, name: undefined }));
            }}
            disabled={isLoading || isProtected || isBaseRole}
            required
            aria-invalid={Boolean(errors.name)}
            aria-describedby={errors.name ? nameErrorId : undefined}
            data-testid="edit-role-name-input"
          />
          <FieldError id={nameErrorId} message={errors.name} testId="edit-role-name-error" />
          {(isProtected || isBaseRole) && (
            <p className="text-xs text-tertiary">
              {isBaseRole
                ? 'Base role names cannot be changed'
                : 'Protected role names cannot be changed'}
            </p>
          )}
        </div>

        {/* Description */}
        <div className="space-y-2">
          <Label htmlFor={descriptionId}>{t('descriptionLabel')}</Label>
          <Textarea
            id={descriptionId}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder={t('descriptionPlaceholder')}
            rows={3}
            disabled={isLoading || isBaseRole}
            data-testid="edit-role-description-input"
          />
          {isBaseRole && (
            <p className="text-xs text-tertiary">{t('baseRoleDescriptionImmutable')}</p>
          )}
        </div>

        {/* Permissions */}
        <div className="space-y-2">
          <Label id={permissionsLabelId}>
            {t('permissionsLabel')}{' '}
