export interface PermissionTreeViewProps {
  /**
   * Array of permission strings
   */
  permissions: string[];

  /**
   * Variant for all nodes
   */
  variant?: 'default' | 'inherited' | 'direct';

  /**
   * Show group headers
   */
  showHeaders?: boolean;

  /**
   * Optional className
   */
  className?: string;
}

function groupPermissions(permissions: string[]): Record<string, string[]> {
  const groups: Record<string, string[]> = {};

  permissions.forEach((perm) => {
    if (perm === '*') {
      groups['wildcard'] = ['*'];
      return;
    }

    const resource = perm.split(':')[0];
    if (!groups[resource]) {
      groups[resource] = [];
    }
    groups[resource].push(perm);
  });

  return groups;
}

/**
 * PermissionTreeView - Hierarchical permission display
 *
 * Features:
 * - Groups permissions by resource (users, roles, sessions, etc.)
 * - Tree-style visualization
 * - Wildcard detection and highlighting
 * - Minimal aesthetic
 *
 * @example
 * ```tsx
 * <PermissionTreeView
 *   permissions={['users:read:all', 'users:update:all', 'roles:*']}
 *   variant="inherited"
 *   showHeaders
 * />
 * ```
 */
export function PermissionTreeView({
  permissions,
  variant = 'default',
  showHeaders = true,
  className,
}: PermissionTreeViewProps) {
  const t = useTranslations('permissions.tree');
  const groupedPermissions = groupPermissions(permissions);

  // Check for wildcard
  const hasWildcard = permissions.includes('*');

  if (permissions.length === 0) {
    return <div className="text-center py-8 text-sm text-muted-foreground">{t('empty')}</div>;
  }

  return (
    <div className={className} data-testid="permission-tree-view">
      {/* Wildcard Warning */}
      {hasWildcard && (
        <div className="mb-4 p-3 rounded-lg bg-warning/10 border border-warning/30">
          <p className="text-sm text-warning-foreground flex items-center gap-2">
            <Shield className="h-4 w-4" aria-hidden="true" />
            <strong>{t('wildcardLabel')}</strong> {t('wildcardNotice')}
          </p>
        </div>
      )}

      {/* Grouped Permissions */}
      <div className="space-y-4">
        {Object.entries(groupedPermissions).map(([resource, perms]) => (
          <div key={resource} className="space-y-2">
            {/* Resource Header */}
            {showHeaders && resource !== 'wildcard' && (
              <h4 className="text-xs uppercase tracking-widest text-tertiary">{resource}</h4>
            )}

            {/* Permission Nodes */}
            <div className="space-y-1">
              {perms.map((perm) => (
                <PermissionNode
                  key={perm}
                  permission={perm}
                  level={resource === 'wildcard' ? 0 : 0}
                  variant={variant}
                />
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
import { memo } from 'react';
import { ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface PermissionNodeProps {
  /**
   * Permission string (e.g., "users:read:all")
   */
  permission: string;

  /**
   * Node depth level for indentation
   */
  level?: number;

  /**
   * Visual variant
   */
  variant?: 'default' | 'inherited' | 'direct';

  /**
   * Optional className
   */
  className?: string;
}

/**
 * PermissionNode - Single permission display in tree
 *
 * Features:
 * - Indentation based on level
 * - Visual variants for inherited/direct permissions
 * - Minimal aesthetic
 *
 * @example
 * ```tsx
 * <PermissionNode permission="users:read:all" level={1} variant="inherited" />
 * ```
 */
export const PermissionNode = memo(function PermissionNode({
  permission,
  level = 0,
  variant = 'default',
  className,
}: PermissionNodeProps) {
  // Parse permission parts
  const parts = permission.split(':');
  const resource = parts[0] || permission;
  const action = parts[1];
  const scope = parts[2];

  // Variant styles
  const variantStyles = {
    default: 'bg-muted border-border text-foreground',
    inherited: 'bg-info/10 border-info/30 text-info-foreground dark:bg-info/20 dark:border-info/40',
    direct:
      'bg-success/10 border-success/30 text-success-foreground dark:bg-success/20 dark:border-success/40',
  };

  return (
    <div
      className={cn(
        'flex items-center gap-2 px-3 py-2 rounded-md border text-xs',
        'transition-all duration-150',
        variantStyles[variant],
        className,
      )}
      style={{ marginInlineStart: `${level * 16}px` }}
      data-testid={`permission-node-${permission}`}
    >
      {level > 0 && (
        <ChevronRight className="h-3 w-3 flex-shrink-0 text-muted-foreground rtl:rotate-180" />
      )}
      <code className="font-mono flex-1">
        <span className="font-semibold">{resource}</span>
        {action && <span className="text-muted-foreground">:{action}</span>}
        {scope && <span className="text-tertiary">:{scope}</span>}
      </code>
    </div>
  );
});

'use client';

import { useId, useSyncExternalStore } from 'react';
import { Link, usePathname } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { FOCUS_RING_CLASSES } from '@/constants/focusStyles';
import { cn } from '@/lib/utils';
import { PermissionGuard } from '@/modules/permissions';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { type NavItem, NAV_SECTIONS, isNavSection } from './navConfig';

const STORAGE_KEY = 'sidebar-collapsed-sections';
const EMPTY_SECTIONS: Record<string, boolean> = {};
let cachedRaw: string | null = null;
let cachedParsed: Record<string, boolean> = EMPTY_SECTIONS;
const listeners = new Set<() => void>();

function getSectionsSnapshot(): Record<string, boolean> {
  if (typeof window === 'undefined') {
    return EMPTY_SECTIONS;
  }
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw !== cachedRaw) {
      cachedRaw = raw;
      cachedParsed = raw ? (JSON.parse(raw) as Record<string, boolean>) : EMPTY_SECTIONS;
    }
  } catch {
    cachedParsed = EMPTY_SECTIONS;
  }
  return cachedParsed;
}

function getServerSectionsSnapshot(): Record<string, boolean> {
  return EMPTY_SECTIONS;
}

function subscribeSections(callback: () => void): () => void {
  listeners.add(callback);
  const onStorage = (e: StorageEvent) => {
    if (e.key === STORAGE_KEY) {
      callback();
    }
  };
  window.addEventListener('storage', onStorage);
  return () => {
    listeners.delete(callback);
    window.removeEventListener('storage', onStorage);
  };
}

function setCollapsedSectionsStorage(
  updater: (prev: Record<string, boolean>) => Record<string, boolean>,
) {
  if (typeof window === 'undefined') return;
  const current = getSectionsSnapshot();
  const next = updater(current);
  try {
    const serialized = JSON.stringify(next);
    window.localStorage.setItem(STORAGE_KEY, serialized);
    cachedRaw = serialized;
    cachedParsed = next;
  } catch {
    // Ignore storage write errors
  }
  listeners.forEach((listener) => listener());
}

export interface DashboardNavProps {
  /**
   * Optional callback when a navigation item is clicked (for mobile auto-close)
   */
  onNavigate?: () => void;
}

export function DashboardNav({ onNavigate }: DashboardNavProps = {}) {
  const pathname = usePathname();
  const t = useTranslations('dashboard.nav');
  const tShell = useTranslations('dashboard.shell');
  const navId = useId();

  const collapsedSections = useSyncExternalStore(
    subscribeSections,
    getSectionsSnapshot,
    getServerSectionsSnapshot,
  );

  const toggleSection = (sectionKey: string) => {
    setCollapsedSectionsStorage((prev) => ({
      ...prev,
      [sectionKey]: !prev[sectionKey],
    }));
  };

  const renderNavItem = (item: NavItem) => {
    const Icon = item.icon;
    const isActive =
      pathname === item.href || (Boolean(pathname) && pathname.startsWith(`${item.href}/`));
    const label = t(item.labelKey);

    const navLink = (
      <Link
        href={item.href}
        onClick={onNavigate}
        aria-current={isActive ? 'page' : undefined}
        className={cn(
          'flex items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-colors',
          isActive
            ? 'bg-primary text-primary-foreground'
            : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground',
          FOCUS_RING_CLASSES,
        )}
        data-testid={`nav-link-${item.labelKey}`}
      >
        <Icon className="h-4 w-4" aria-hidden="true" />
        {label}
      </Link>
    );

    // If no permission required, always show
    if (!item.permission && !item.permissions && !item.anyPermissions) {
      return <div key={item.href}>{navLink}</div>;
    }

    // Wrap with permission guard
    return (
      <PermissionGuard
        key={item.href}
        permission={item.permission}
        permissions={item.permissions}
        anyPermissions={item.anyPermissions}
      >
        {navLink}
      </PermissionGuard>
    );
  };

  return (
    <nav className="space-y-1" aria-label={tShell('mainNavigation')} data-testid="dashboard-nav">
      {NAV_SECTIONS.map((item) => {
        if (isNavSection(item)) {
          // Collapsible Section
          const isCollapsed = collapsedSections[item.titleKey] ?? false;
          const SectionIcon = item.icon;
          const sectionTitle = t(item.titleKey);
          const sectionItemsId = `${navId}-${item.titleKey}`;

          return (
            <PermissionGuard
              key={item.titleKey}
              permission={item.permission}
              permissions={item.permissions}
              anyPermissions={item.anyPermissions}
            >
              <div className="space-y-1">
                {/* Section Header */}
                <button
                  type="button"
                  onClick={() => toggleSection(item.titleKey)}
                  aria-expanded={!isCollapsed}
                  aria-controls={sectionItemsId}
                  className={cn(
                    'flex w-full items-center justify-between rounded-lg px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground',
                    FOCUS_RING_CLASSES,
                  )}
                  data-testid={`nav-section-${item.titleKey}`}
                >
                  <div className="flex items-center gap-3">
                    <SectionIcon className="h-4 w-4" aria-hidden="true" />
                    <span>{sectionTitle}</span>
                  </div>
                  {isCollapsed ? (
                    <ChevronRight className="h-4 w-4 rtl:rotate-180" aria-hidden="true" />
                  ) : (
                    <ChevronDown className="h-4 w-4" aria-hidden="true" />
                  )}
                </button>

                {/* Section Items */}
                {!isCollapsed && (
                  <div
                    id={sectionItemsId}
