                    data-testid={`nav-section-items-${item.titleKey}`}
                  >
                    {item.items.map(renderNavItem)}
                  </div>
                )}
              </div>
            </PermissionGuard>
          );
        }

        // Regular nav item (top-level)
        return renderNavItem(item);
      })}
    </nav>
  );
