            <div className="flex w-full flex-col gap-2 lg:w-auto lg:flex-row lg:shrink-0">
              {!isPrimary && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleSetPrimary}
                  disabled={isSettingPrimary || isUnlinking}
