                  disabled={isUnlinking || isSettingPrimary}
                  className="w-full whitespace-nowrap lg:w-auto"
                  data-testid={`unlink-${providerId}`}
                >
                  {isUnlinking ? (
                    <Loader2
                      className="h-4 w-4 shrink-0 motion-safe:animate-spin"
