 15	    /**
 16	     * Get all roles with pagination
 17	     */
 18	    listRoles: builder.query<ListRolesResponse, ListRolesQuery | undefined>({
 19	      query: (params = {}) => ({
 20	        url: '/api/roles',
 21	        params,
 22	      }),
 23	      transformResponse: (response: {
 24	        success: boolean;
 25	        data: {
 26	          roles: Role[];
 27	          total: number;
 28	          page: number;
 29	          pages?: number;
 30	          totalPages?: number;
 31	          limit?: number;
 32	        };
 33	      }): ListRolesResponse => {
 34	        const raw = response.data;
 35	        const limit = raw.limit ?? 20;
 36	        const totalPages =
 37	          raw.totalPages ?? raw.pages ?? Math.max(1, Math.ceil((raw.total || 0) / limit));
 38	        return {
 39	          roles: raw.roles,
 40	          total: raw.total,
 41	          page: raw.page,
 42	          limit,
 43	          totalPages,
 44	        };
 45	      },
 46	      providesTags: ['Roles'],
 47	    }),
 48	
 49	    /**
 50	     * Get single role by ID or slug
 51	     */
 52	    getRole: builder.query<Role, string>({
