  --card: 0 0% 100%;
  --card-foreground: 224 71% 6%;

  /* Popover surfaces */
  --popover: 0 0% 100%;
  --popover-foreground: 224 71% 6%;

  /* Primary action color */
  --primary: 239 65% 50%;
  --primary-foreground: 0 0% 100%;

  /* Secondary surfaces */
  --secondary: 220 14% 96%;
  --secondary-foreground: 224 71% 6%;

  /* Muted surfaces and text */
  --muted: 220 14% 96%;
  --muted-foreground: 220 10% 40%;
  --text-tertiary: 220 8% 45%;

  /* Accent highlights */
  --accent: 220 14% 96%;
  --accent-foreground: 224 71% 6%;

  /* Destructive actions */
  --destructive: 0 72% 45%;
  --destructive-foreground: 0 0% 100%;

