        await forgotPassword({
          email: data.email,
        }).unwrap();

        // Show success toast
        toast.success(tToast('success.resetLinkSent'));

        // Redirect to reset password page with email
        router.push(`/auth/reset-password?email=${encodeURIComponent(data.email)}`);
