            <FormPassword<ChangePasswordFormData>
              name="confirmPassword"
              label={t('confirmPassword')}
              placeholder="********"
              disabled={isLoading}
              data-testid="confirm-password-input"
            />

            <SubmitButton
              isLoading={isLoading}
              className="h-10 mt-0 w-full py-2"
