/** A symbol with every function pattern in place and nothing else. */
export function createSymbol(version: number): QrSymbol {
  const size = 4 * version + 17;
  const symbol: QrSymbol = {
    version,
    size,
    modules: grid(size),
    reserved: grid(size),
