  drawFinder(symbol, 3, 3);
  drawFinder(symbol, 3, size - 4);
  drawFinder(symbol, size - 4, 3);
  drawAlignmentPatterns(symbol);
  drawTimingPatterns(symbol);
  reserveFormatAreas(symbol);
  reserveVersionAreas(symbol);

