export const QR_MIN_VERSION = 1;

export const QR_MAX_VERSION = 10;

/** Byte mode. */
export const MODE_INDICATOR = 0b0100;

/** Level M in the two format bits. L is 01, M is 00, Q is 11, H is 10. */
