    // Toggle section
    await adminSection.click();
    await expect(usersLink).toBeVisible({ visible: !initialVisibility });

    // Visibility should change
    const newVisibility = await usersLink.isVisible();
    expect(newVisibility).toBe(!initialVisibility);
  });
});

