import { forwardRef, HTMLAttributes, ReactNode } from 'react';
import { cn } from '@/lib/utils';

export interface TimelineListProps<T> extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * Array of items to render
   */
  items: T[];

  /**
   * Render function for each item
   */
  renderItem: (item: T, index: number) => ReactNode;

  /**
   * Highlight a specific item (e.g., current session)
   */
  highlightIndex?: number;

  /**
   * Enable stagger animation for items
   */
  stagger?: boolean;
}

/**
 * TimelineList - Vertical timeline layout
 *
 * Features:
 * - Vertical list with timeline aesthetic
 * - Optional highlighted item
 * - Stagger animations on mount
 * - Chronological order visualization
 * - Responsive spacing
 *
 * @example
 * ```tsx
 * <TimelineList
 *   items={sessions}
 *   renderItem={(session, index) => (
 *     <SessionCardTimeline session={session} isCurrent={session.isCurrent} />
 *   )}
 *   highlightIndex={sessions.findIndex(s => s.isCurrent)}
 *   stagger
 * />
 * ```
 */
export const TimelineList = forwardRef(
  <T,>(
    {
      items,
      renderItem,
      highlightIndex,
      stagger = false,
      className,
      ...props
    }: TimelineListProps<T>,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    return (
      <div
        ref={ref}
        data-testid="timeline-list"
        className={cn('flex flex-col space-y-4', className)}
        {...props}
      >
        {items.map((item, index) => {
          const isHighlighted = highlightIndex !== undefined && index === highlightIndex;

          return (
            <div
              key={index}
              data-testid={`timeline-item-${index}`}
              className={cn(
                'transition-all duration-300 ease-out',
                stagger && 'motion-safe:animate-slide-up motion-safe:stagger-animation',
                isHighlighted && 'scale-[1.02]',
              )}
              style={stagger ? ({ '--index': index } as React.CSSProperties) : undefined}
            >
              {renderItem(item, index)}
            </div>
          );
        })}
      </div>
    );
  },
) as (<T>(
  props: TimelineListProps<T> & { ref?: React.ForwardedRef<HTMLDivElement> },
) => React.ReactElement) & { displayName?: string };

TimelineList.displayName = 'TimelineList';
import { forwardRef, HTMLAttributes, ReactNode } from 'react';
import { cn } from '@/lib/utils';

export interface SplitViewProps extends Omit<HTMLAttributes<HTMLDivElement>, 'content'> {
  /**
   * Sidebar content (left side)
   */
  sidebar: ReactNode;

  /**
   * Main content (right side)
   */
  content: ReactNode;

  /**
   * Sidebar width as percentage or pixels
   */
  sidebarWidth?: string;

  /**
   * Make sidebar sticky
   */
  stickySidebar?: boolean;
}

/**
 * SplitView - Responsive sidebar + content layout
 *
 * Features:
 * - Desktop: Side-by-side layout
 * - Mobile: Stacked layout (sidebar on top)
 * - Optional sticky sidebar
 * - Configurable sidebar width
 * - Smooth transitions
 *
 * @example
 * ```tsx
 * <SplitView
 *   sidebar={<RoleSidebarNav roles={roles} />}
 *   content={<RoleDetailPanel role={selectedRole} />}
 *   sidebarWidth="25%"
 *   stickySidebar
 * />
 * ```
 */
export const SplitView = forwardRef<HTMLDivElement, SplitViewProps>(
  ({ sidebar, content, sidebarWidth = '25%', stickySidebar = true, className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        data-testid="split-view"
        className={cn('flex flex-col md:flex-row gap-6', className)}
        {...props}
      >
        {/* Sidebar */}
        <aside
          className={cn(
            'md:w-[var(--sidebar-width)]',
            stickySidebar && 'md:sticky md:top-0 md:self-start md:max-h-screen md:overflow-y-auto',
          )}
          style={{ '--sidebar-width': sidebarWidth } as React.CSSProperties}
          data-testid="split-view-sidebar"
        >
          {sidebar}
        </aside>

        {/* Content pane. Not a <main>: the page layout owns the single one */}
        <div className="flex-1 min-w-0" data-testid="split-view-content">
          {content}
        </div>
      </div>
    );
  },
);

SplitView.displayName = 'SplitView';
'use client';

import { memo, ReactNode } from 'react';
import { useTranslations } from 'next-intl';
import { SectionHeader } from '@/components/design-system';
import { cn } from '@/lib/utils';

export interface UserListSectionProps {
  /**
   * Section identifier
   */
  id: string;

  /**
   * Section title
   */
  title: string;

  /**
   * Number of items in this section
   */
  count: number;

  /**
   * Section content (user cards)
   */
  children: ReactNode;

  /**
   * Optional action buttons
   */
  actions?: ReactNode;

  /**
   * Initially collapsed state
   */
  initiallyCollapsed?: boolean;

  /**
   * Collapsed state (controlled)
   */
  collapsed?: boolean;

  /**
   * Callback when collapse state changes
   */
  onCollapse?: (collapsed: boolean) => void;

  /**
   * Optional className
   */
  className?: string;
}

/**
 * UserListSection - Collapsible section for grouped users
 *
 * Features:
 * - Collapsible header with count
 * - Smooth expand/collapse animations
 * - Optional actions
 * - Grid layout for user cards
 * - Optimized with React.memo
 *
 * @example
 * ```tsx
 * <UserListSection
 *   id="verified"
 *   title="Verified Users"
 *   count={18}
 *   collapsed={isCollapsed}
 *   onCollapse={setIsCollapsed}
 * >
 *   {verifiedUsers.map(user => (
 *     <UserCard key={user._id} user={user} />
 *   ))}
 * </UserListSection>
 * ```
 */
export const UserListSection = memo(function UserListSection({
  id,
  title,
  count,
  children,
  actions,
  collapsed = false,
  onCollapse,
  className,
}: UserListSectionProps) {
  const t = useTranslations('users.list');
  const gridId = `user-grid-${id}`;

  return (
    <section data-testid={`user-list-section-${id}`} className={cn('space-y-4', className)}>
      {/* Section Header */}
      <SectionHeader
        title={title}
        count={count}
        actions={actions}
        collapsible
        collapsed={collapsed}
        onCollapse={onCollapse}
        contentId={gridId}
      />

      {/* User Grid - Animated Collapse */}
      {!collapsed && (
        <div
          id={gridId}
          className={cn('grid gap-4 md:grid-cols-2 lg:grid-cols-3', 'motion-safe:animate-fade-in')}
          data-testid={gridId}
        >
          {children}
        </div>
      )}

      {/* Empty State */}
      {!collapsed && count === 0 && (
        <div className="py-8 text-center text-sm text-muted-foreground">{t('emptyGroup')}</div>
      )}
    </section>
  );
});

