import { useEffect } from 'react';
import { useSearchParams } from 'next/navigation';
import { useRouter } from '@/i18n/navigation';
import { useAppSelector } from '@/store/hooks';
import { selectIsAuthenticated, selectUser } from '../store/authSlice';
import { signedInPath } from '../utils/signInRouting';
import { REDIRECT_PARAM } from '../constants/authMethods';
import { AuthLayout } from '../components/AuthLayout';
import { LoginForm } from '../components/LoginForm';

/**
 * LoginPage component
 * Renders the login form within the auth layout
 * Redirects to dashboard if user is already authenticated
 *
 * @example
 * // In Next.js route
 * export default function LoginRoute() {
 *   return <LoginPage />;
 * }
 */
export function LoginPage() {
  const router = useRouter();
  const isAuthenticated = useAppSelector(selectIsAuthenticated);
  const user = useAppSelector(selectUser);
  const redirect = useSearchParams().get(REDIRECT_PARAM);

  useEffect(() => {
    if (isAuthenticated && user) {
      router.replace(signedInPath(user, redirect));
    }
  }, [isAuthenticated, user, redirect, router]);

  // Don't render login form if already authenticated
  if (isAuthenticated) {
    return null;
  }

  return (
    <AuthLayout>
      <LoginForm />
    </AuthLayout>
  );
}
'use client';

import { useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, usePathname } from '@/i18n/navigation';
import { LoadingRegion } from '@/components/layout/LoadingRegion';
import { useAppSelector } from '@/store/hooks';
import { selectIsAuthenticated, selectAuthLoading } from '@/modules/auth/store/authSlice';

interface AuthGuardProps {
  readonly children: React.ReactNode;
}

/**
 * AuthGuard component to protect routes requiring authentication
 * Redirects unauthenticated users to login page with return URL
 * Relies on AuthProvider for global session validation
 *
 * @example
 * // In a protected page
 * export default function DashboardPage() {
 *   return (
 *     <AuthGuard>
 *       <Dashboard />
 *     </AuthGuard>
 *   );
 * }
 */
export function AuthGuard({ children }: Readonly<AuthGuardProps>) {
  const t = useTranslations('common');
  const router = useRouter();
  const pathname = usePathname();
  const isAuthenticated = useAppSelector(selectIsAuthenticated);
  const isAuthLoading = useAppSelector(selectAuthLoading);

  useEffect(() => {
    // Wait for auth state to be determined
    if (isAuthLoading) {
      return;
    }

    // If not authenticated, redirect to login with return URL
    if (!isAuthenticated) {
      const returnUrl = encodeURIComponent(pathname);
      router.push(`/auth/login?redirect=${returnUrl}`);
    }
  }, [isAuthenticated, isAuthLoading, pathname, router]);

  // Announce the wait instead of leaving a blank screen, both while the auth
  // state resolves and while the redirect to login is in flight
  if (isAuthLoading || !isAuthenticated) {
    return <LoadingRegion label={t('loading')} testId="auth-guard-loading" />;
  }

  // User is authenticated, render children
  return <>{children}</>;
}
import {
  ADMIN_PERMISSIONS,
  ADMIN_SIGNED_IN_PATH,
  DEFAULT_SIGNED_IN_PATH,
  REDIRECT_PARAM,
  TWO_FACTOR_PATH,
} from '../constants/authMethods';
import type { User } from '../types/auth.types';
import { getRedirectPath } from './authHelpers';

/** Where an account lands when the sign-in carried no redirect of its own. */
export function defaultPathFor(user: User | null): string {
  const permissions = user?.permissions ?? [];
  const isAdmin = ADMIN_PERMISSIONS.some((permission) => permissions.includes(permission));
  return isAdmin ? ADMIN_SIGNED_IN_PATH : DEFAULT_SIGNED_IN_PATH;
}

/** The page to open once a sign-in finishes, rejecting off-site redirects. */
export function signedInPath(user: User | null, redirect?: string | null): string {
  return getRedirectPath(redirect, defaultPathFor(user));
}

/**
 * The challenge page, with the requested page carried across so the second
 * factor does not lose it.
 */
export function twoFactorPath(redirect?: string | null): string {
  if (!redirect) {
    return TWO_FACTOR_PATH;
  }
  return `${TWO_FACTOR_PATH}?${REDIRECT_PARAM}=${encodeURIComponent(redirect)}`;
}
